//! 🪺️ The actual original registry transfers only paid handles, including its first cold admission.
use crate::{BoundedJob, JOBS, JOB_KIND_INFER, JOB_KIND_IO_SNIFF, JOB_SLOTS, JobBody, OriginalJobKindLookup, OriginalJobKindLookupStep, abi, builtin_factory, cancel_job, close_body, close_original, has_owned_jobs, register_bounded_job_kind, start_job};
use semio_framework_value_derive::{FromValue, ToValue};
use std::future::Future;
use semio_framework_actor::OriginalJobStep as JobStep;
use semio_framework::kernel::OriginalJobSource as OriginalJobAdmission;
use semio_framework_value::{ValueError, ValueRefusalKind};
use semio_framework_job::{Generation, OperationId, StepBudget, StepContext, root_cancel_token};
use semio_framework_value::{RetainedCloneGrant, RetainedCloneProgress};

/// 🧫️ Cold authority setup and source construction precede the measured actual registry scope.
#[test]
fn original_job_registry_cold_admission_denial_and_saturation_preserve_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 let raw=fixture["text"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize).into_bytes();
 let g=&fixture["registryGrant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());let cancel=root_cancel_token();let mut sequence=0;
 let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(raw.clone()),checkpoint:None});let original=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{
  let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
  let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(start_job(&mut source,&mut cx)));
  assert!(!result.unwrap());assert_eq!(source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),original);assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }
 for job in 1..=JOB_SLOTS as u64{
  if job!=1{source=Some(OriginalJobAdmission{job,kind:JOB_KIND_INFER.into(),input:Some(raw.clone()),checkpoint:None})}
  let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
  let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(start_job(&mut source,&mut cx)));
  assert!(result.unwrap());assert!(source.is_none());assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==job).unwrap();assert_eq!(slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer)});
 }
 source=Some(OriginalJobAdmission{job:JOB_SLOTS as u64+1,kind:JOB_KIND_INFER.into(),input:Some(raw),checkpoint:None});let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(start_job(&mut source,&mut cx)));
 assert!(!result.unwrap());assert_eq!(source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer);assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(cx);
 let cleanup=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:262144,maximum_release_bytes:262144,maximum_depth:128};
 JOBS.with(|slots|{let mut slots=slots.borrow_mut();for entry in slots.iter_mut(){let Some(slot)=entry.as_mut()else{continue};for _ in 0..10000{let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,cleanup),cancel.clone(),||Some(1),&mut sequence,&mut receipt);if close_body(slot,&mut cx).unwrap()&&close_original(&mut slot.source,&mut slot.source_close,&mut cx).unwrap(){break}}assert!(slot.body.is_none()&&slot.source.is_none()&&slot.source_close.is_none());*entry=None}});
 let mut closing=None;for _ in 0..10000{let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,cleanup),cancel.clone(),||Some(1),&mut sequence,&mut receipt);if close_original(&mut source,&mut closing,&mut cx).unwrap(){break}}assert!(source.is_none()&&closing.is_none());
 eprintln!("[DEBUG] original job registry coldAdmissionSystem0=true deniedSourceSame=true saturatedSourceSame=true exactMetadataReceipt=true; cleanup outside measured admission scope");
}

/// 🔬️ Every real source and static candidate byte needs its own original copy turn.
#[test]
fn original_job_kind_lookup_preserves_denied_frontiers_and_whole_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();
 let factory=builtin_factory(JOB_KIND_IO_SNIFF).unwrap();for kind in ["semio.artifact-infer","semio.artifact-infer-long","未知","未知🌊x"]{assert!(register_bounded_job_kind(kind,factory))}
 let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());
 let value=&fixture["executionGrant"];let original_grant=RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize};let mut cases=0;
 for row in fixture["lookupCases"].as_array().unwrap(){for copy in [1,3,64]{for cut in [None,Some(0),Some(3),Some(17)]{
  let mut source=Some(row["input"].as_str().unwrap().to_string());let pointer=source.as_ref().unwrap().as_ptr();let cancel=root_cancel_token();let mut sequence=0;let mut cursor=OriginalJobKindLookup::new();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut terminal=false;
  for turn in 0..10000{
   if cut==Some(turn){cancel.cancel_now()}
   let demand=cursor.demand(source.as_ref().unwrap());let before=(cursor.epoch,cursor.index,cursor.offset,cursor.left,cursor.candidate.map(|candidate|candidate.kind));
   for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}]{
    if denied.maximum_items>0&&denied.maximum_depth>0&&demand.maximum_copy_bytes==0{continue}
    let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
    let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.as_ref().unwrap(),&mut cx));assert!(matches!(step.unwrap(),OriginalJobKindLookupStep::Pending));assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((cursor.epoch,cursor.index,cursor.offset,cursor.left,cursor.candidate.map(|candidate|candidate.kind)),before);assert_eq!(source.as_ref().unwrap().as_ptr(),pointer);
   }
   let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);
   let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.as_ref().unwrap(),&mut cx));let step=step.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cx.retained_progress().fits(grant));assert!(cx.retained_progress().copied_bytes<=1);assert_eq!(source.as_ref().unwrap().as_ptr(),pointer);
   if cancel.is_cancelled_now(){assert!(matches!(step,OriginalJobKindLookupStep::Pending));assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());terminal=true;break}
   match step{OriginalJobKindLookupStep::Pending=>{},OriginalJobKindLookupStep::Found(candidate)=>{let expected=row["matched"].as_u64().unwrap()as usize;assert_eq!(candidate.kind,row["candidates"][expected].as_str().unwrap());terminal=true;break},OriginalJobKindLookupStep::Missing=>{assert!(row["matched"].is_null());terminal=true;break}}
  }
  assert!(terminal);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut closing=None;let mut emptied=false;
  for _ in 0..10000{let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,..original_grant}),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original(&mut source,&mut closing,&mut cx));assert_eq!((heap.requested_bytes,heap.released_bytes),(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));if result.unwrap(){emptied=true;break}}
  assert!(emptied&&source.is_none()&&closing.is_none());cases+=1;
 }}}
 eprintln!("[DEBUG] original job kind lookup cases={cases} deniedFrontierSame=true originalPointerSame=true separateSourceAndStaticByteTurns=true SystemConservation=true terminalDrop0=true");
}

/// 🛑️ Original cancellation admits only a funded same-identity metadata signal.
#[test]
fn original_job_cancellation_preserves_denied_and_foreign_sources(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();let g=&fixture["registryGrant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};let operation=OperationId(fixture["caller"]["operation"].as_u64().unwrap());let generation=Generation(fixture["caller"]["generation"].as_u64().unwrap());let cancel=root_cancel_token();let mut sequence=0;let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(fixture["text"].as_str().unwrap().repeat(fixture["repeat"].as_u64().unwrap()as usize).into_bytes()),checkpoint:None});let pointer=source.as_ref().unwrap().input.as_ref().unwrap().as_ptr();
 {let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);assert!(semio_framework_async::poll::resolve_ready(start_job(&mut source,&mut cx)).unwrap());}
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(cancel_job(1,&mut cx)));assert!(!result.unwrap());assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let original=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert!(!original.cancelled);assert_eq!(original.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer)});}
 for identity in [(OperationId(operation.0+1),generation),(operation,Generation(generation.0+1))]{let mut receipt=Default::default();let mut cx=StepContext::new(identity.0,identity.1,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(cancel_job(1,&mut cx)));assert_eq!(result.unwrap_err().kind,semio_framework_value::ValueRefusalKind::OwnershipLimit);assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|assert!(!slots.borrow().iter().flatten().find(|slot|slot.job==1).unwrap().cancelled));}
 {let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_async::poll::resolve_ready(cancel_job(1,&mut cx)));assert!(result.unwrap());assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let original=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert!(original.cancelled);assert_eq!(original.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr(),pointer);assert!(matches!(original.body,Some(JobBody::Resolving(_))));});}
 let g=&fixture["executionGrant"];let cleanup=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};JOBS.with(|slots|{let mut slots=slots.borrow_mut();let index=slots.iter().position(|slot|slot.as_ref().is_some_and(|slot|slot.job==1)).unwrap();let original=slots[index].as_mut().unwrap();for _ in 0..10000{let mut receipt=Default::default();let mut cx=StepContext::new(operation,generation,StepBudget::new(1,u64::MAX,cleanup),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||Ok::<_,semio_framework_value::ValueError>(close_body(original,&mut cx)?&&close_original(&mut original.source,&mut original.source_close,&mut cx)?));assert_eq!((heap.requested_bytes,heap.released_bytes),(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));if done.unwrap(){break}}assert!(original.body.is_none()&&original.source.is_none()&&original.source_close.is_none());slots[index]=None;});
 eprintln!("[DEBUG] original job cancellation deniedSourceSame=true foreignIdentitySame=true admittedMetadataSystem0=true actualReceipt=true fullSourceCleanupConserved=true");
}

/// 🛑️ Actual canceled controls borrow the initiating token until their terminal paid reply.
#[test]
fn original_job_cancelled_context_publishes_terminal_reply_after_paid_close(){
 use semio_framework_job::{CancelToken,JobPayloadAuthority};
 use semio_framework_value::retirement::RetirementCursor;
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️extension/🧪️tests/🧫️fixtures/📨️invoke/🔣️.json")).unwrap();let operation=OperationId(corpus["caller"]["operation"].as_u64().unwrap());let generation=Generation(corpus["caller"]["generation"].as_u64().unwrap());let g=&corpus["executionGrant"];let original=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 for copy in corpus["failureCopyGrants"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize){
  let grant=RetainedCloneGrant{maximum_copy_bytes:copy,..original};let((cancel,birth),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||CancelToken::admit_root(grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(birth.retained_capacity_bytes,birth.released_bytes));let((mut authority,birth),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(birth.retained_capacity_bytes,birth.released_bytes));let mut sequence=0;let mut source=Some(OriginalJobAdmission{job:1,kind:JOB_KIND_INFER.into(),input:Some(corpus["text"].as_str().unwrap().repeat(corpus["repeat"].as_u64().unwrap()as usize).into_bytes()),checkpoint:Some(vec![7;257])});
  {let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,||Some(1),&mut sequence,&mut receipt,&authority).unwrap();let(admitted,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::start(&mut source,&mut cx));assert!(admitted.unwrap());assert!(source.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});}
  cancel.cancel_now();let mut output=None;
  for denied in corpus["jobWorkDenials"].as_array().unwrap(){let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(denied["fuel"].as_u64().unwrap(),denied["deadline"].as_u64().unwrap(),grant),&cancel,||Some(1),&mut sequence,&mut receipt,&authority).unwrap();let before=JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==1).unwrap();(slot.cancellation_signalled,slot.cancellation_fault_started,slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr())});let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::step(1,&mut cx));assert!(step.unwrap().is_none());assert_eq!(cx.retained_progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));JOBS.with(|slots|{let slots=slots.borrow();let slot=slots.iter().flatten().find(|slot|slot.job==1).unwrap();assert_eq!((slot.cancellation_signalled,slot.cancellation_fault_started,slot.source.as_ref().unwrap().input.as_ref().unwrap().as_ptr()),before)});}
  for turn in 0..100000{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1024,u64::MAX,grant),&cancel,||Some(1),&mut sequence,&mut receipt,&authority).unwrap();assert!(cx.is_cancelled());assert!(std::ptr::eq(cx.borrowed_original_cancel_token().unwrap(),&cancel));let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||abi::step(1,&mut cx));let step=step.unwrap();assert!(cx.retained_progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));match step{None=>assert!(has_owned_jobs(operation.0,generation.0)),Some(JobStep::Failed(bytes))=>{assert!(!has_owned_jobs(operation.0,generation.0));output=Some(bytes);break},_=>panic!("canceled original job returned another outcome")};assert!(turn<99999,"original canceled context did not finish its paid terminal reply copy={copy}");}
  let decoded:serde_json::Value=semio_framework_os_kernel::os_pack::pack_rt::decode_wire_value(output.as_ref().unwrap()).unwrap().into();assert_eq!(decoded["code"],corpus["cancelledJobReply"]["code"]);assert_eq!(decoded["message"],corpus["cancelledJobReply"]["message"]);let mut closing=None;
  for _ in 0..10000{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,||Some(1),&mut sequence,&mut receipt,&authority).unwrap();let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close_original(&mut output,&mut closing,&mut cx));assert_eq!((heap.requested_bytes,heap.released_bytes),(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));if done.unwrap(){break}}assert!(output.is_none()&&closing.is_none());
  let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||authority.close_step(grant).unwrap());assert!(authority.terminal_is_empty());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));let mut token=semio_framework_async::CancelTokenRetirement::from_token(cancel);for _ in 0..10000{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||token.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if token.terminal_is_empty(){break}}assert!(token.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop((authority,token,output,closing)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  eprintln!("[DEBUG] original canceled job copy={copy} sameBorrowedToken=true paidSourceClose=true terminalReply=true SystemConservation=true separateAuthorityClose=true terminalDrop0=true");
 }
}
